 "content": "def transform(grid):
    """Extend a full-length divider's adjacent motif with an 8-colored stripe."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Locate the full straight divider (color 2 in the demonstrations).
    lines = []
    for r in range(h):
        vals = set(grid[r])
        if len(vals) == 1 and next(iter(vals)) != bg:
            lines.append(("row", r, next(iter(vals))))
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1 and next(iter(vals)) != bg:
            lines.append(("col", c, next(iter(vals))))
    if not lines:
        raise ValueError("No full-length divider found")
    orientation, divider, divider_color = lines[0]

    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, divider_color)]
    if not pts:
        raise ValueError("No motif found beside divider")
    if orientation == "col":
        lo, hi = min(c for r, c in pts), max(c for r, c in pts)
        stripe = lo - 1 if divider > hi else hi + 1
        out = [row[:] for row in grid]
        if not 0 <= stripe < w:
            raise ValueError("Stripe lies outside grid")
        for r in range(h):
            out[r][stripe] = 8
    else:
        lo, hi = min(r for r, c in pts), max(r for r, c in pts)
        stripe = lo - 1 if divider > hi else hi + 1
        out = [row[:] for row in grid]
        if not 0 <= stripe < h:
            raise ValueError("Stripe lies outside grid")
        out[stripe] = [8] * w
    return out

